+export const getSyncsRetryUrl = (id: string) => `/admin/syncs/${id}/retry`
+
+export const syncsRetry = async (id: string, options?: RequestInit): Promise<OrderSync> => {
+  const res = await fetch(getSyncsRetryUrl(id), { ...options, method: "POST" })
+  const body = [204, 205, 304].includes(res.status) ? null : await res.text()
+  const data: OrderSync = body ? JSON.parse(body) : {}
+  return syncsRetry200.parse(data)
+}
